pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }
    function testFuzz_property(uint256 plays) public {
        plays = bound(plays, 1, 100);
        address player = address(0x100);
        vm.deal(player, plays * 10 ether);
        for (uint i = 0; i < plays; i++) {
            vm.prank(player);
            c.play{value: 10}();
        }
        assertTrue(address(c).balance - c.pot() == 0);
    }
}
